--
-- Table structure for table `company_sampling_records`
--

DROP TABLE IF EXISTS `company_sampling_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `company_sampling_records` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company_id` int NOT NULL,
  `announcement_id` int NOT NULL,
  `announcement_detail_id` int NOT NULL,
  `product_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `product_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'cosmetics',
  `announcement_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sampling',
  `sampled_at` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_company_sampling_detail_company` (`announcement_detail_id`,`company_id`),
  KEY `idx_company_sampling_company` (`company_id`),
  KEY `idx_company_sampling_announcement` (`announcement_id`),
  KEY `idx_company_sampling_product_type` (`product_type`),
