DROP TABLE IF EXISTS `unqualified_product_tree_rollups`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `unqualified_product_tree_rollups` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `unqualified_product_id` int NOT NULL,
  `source_key` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_label` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source_title` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_publish_date` datetime DEFAULT NULL,
  `province_display` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `manufacturer_province` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '未标注省份',
  `manufacturer_city` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '未标注城市',
  `sampled_province` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '未标注省份',
  `sampled_city` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '未标注城市',
  `product_category` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `issue_item` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `year_value` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_unqualified_product_tree_rollup` (`unqualified_product_id`,`source_key`,`province_display`,`product_category`,`issue_item`,`year_value`),
  KEY `idx_uptr_product` (`unqualified_product_id`),
  KEY `idx_uptr_source_key` (`source_key`),
  KEY `idx_uptr_province` (`province_display`),
  KEY `idx_uptr_product_category` (`product_category`),
  KEY `idx_uptr_issue_item` (`issue_item`),
  KEY `idx_uptr_year_value` (`year_value`),
  KEY `idx_uptr_manufacturer_region` (`manufacturer_province`,`manufacturer_city`),
  KEY `idx_uptr_sampled_region` (`sampled_province`,`sampled_city`),
  CONSTRAINT `fk_uptr_unqualified_product` FOREIGN KEY (`unqualified_product_id`) REFERENCES `unqualified_products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2054 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
